  { key: "id", label: "ID", w: 70 },
  { key: "vendor", label: "Vendor", w: 190 },
  { key: "billing_id", label: "Billing ID", w: 150 },
  { key: "service_account", label: "Service Account", w: 160 },
  { key: "meter_id", label: "Meter ID", w: 140 },
  { key: "utility", label: "Utility", w: 110 },
  { key: "type", label: "Type", w: 130 },
  { key: "last_bill", label: "Last Bill", w: 110 },
  { key: "open_closed", label: "Open/Closed", w: 120 }
];

function badge(s) {
  if (s === "Need Pair") return React.createElement("span", { className: "badge b-need" }, "Need Pair");
  if (s === "Pair") return React.createElement("span", { className: "badge b-pair" }, "Pair");
  if (s === "No Pair") return React.createElement("span", { className: "badge b-no" }, "No Pair");
  return "";
}

