  const data = (model && model.data) || [];
  const site = (model && model.site) || "";
  const close = () => appsmith.triggerEvent("onClose");

  const filtered = useMemo(() => {
    const t = q.trim().toLowerCase();
    if (!t) return data;
    return data.filter((r) => ["vendor","billing_id","service_account","meter_id","utility"].some((k) => r[k] != null && String(r[k]).toLowerCase().indexOf(t) !== -1));
  }, [data, q]);

  const rows = useMemo(() => {
    const l = filtered.slice();
    l.sort((a, b) => {
      if (sortKey === "id") { const av = Number(a.id)||0, bv = Number(b.id)||0; return sortDir === "asc" ? av-bv : bv-av; }
      const av = a[sortKey]==null?"":String(a[sortKey]), bv = b[sortKey]==null?"":String(b[sortKey]);
      return sortDir === "asc" ? av.localeCompare(bv) : bv.localeCompare(av);
    });
    return l;
