  const pageRows = rows.slice((safePage-1)*pageSize, (safePage-1)*pageSize + pageSize);
  const onSort = (k) => { if (k === sortKey) setSortDir(sortDir==="asc"?"desc":"asc"); else { setSortKey(k); setSortDir("asc"); } };
  const toggle = (id) => setSel((s) => { const n = {...s}; if (n[id]) delete n[id]; else n[id]=true; return n; });

