      React.createElement("button", { className: "fbtn" }, "Filters \u2261")),
    React.createElement("div", { className: "meta" },
      React.createElement("span", null, "Virtual Accounts total: ", React.createElement("b", { style: { color: "#e2e8f0" } }, rows.length)),
      React.createElement("a", { className: "lnk" }, "Select All"),
      React.createElement("a", { className: "lnk", style: { color: "#64748b" } }, "Clear All"),
      React.createElement("span", { className: "rt" },
        React.createElement("a", null, "Remap"),
        React.createElement("a", null, "Unpair"))),
    React.createElement("div", { className: "scroll" },
      React.createElement("table", { className: "tbl" },
        React.createElement("thead", null,
          React.createElement("tr", null,
            React.createElement("th", { style: { width: "40px" } }, ""),
            React.createElement("th", { style: { width: "96px" } }, ""),
            COLS.map((c) => React.createElement("th", { key: c.key, style: { width: c.w + "px" }, onClick: () => onSort(c.key) }, c.label)),
            React.createElement("th", { style: { width: "230px" } }, ""))),
        React.createElement("tbody", null,
          pageRows.length === 0
