                COLS.map((c) => React.createElement("td", { key: c.key }, cell(r, c.key))),
                React.createElement("td", null,
                  React.createElement("a", { className: "rowlnk" }, "Link"),
                  React.createElement("a", { className: "rowlnk" }, "Bill History"),
                  React.createElement("a", { className: "rowlnk" }, "Details")))))) ),
    React.createElement("div", { className: "pager" },
      React.createElement("button", { className: "pbtn", disabled: safePage <= 1, onClick: () => setPage(safePage-1) }, "\u2039"),
      React.createElement("span", { className: "pnum" }, safePage),
      React.createElement("span", { className: "gl" }, "of " + totalPages),
      React.createElement("button", { className: "pbtn", disabled: safePage >= totalPages, onClick: () => setPage(safePage+1) }, "\u203A"),
      React.createElement("select", { className: "psize", value: pageSize, onChange: (e) => { setPageSize(Number(e.target.value)); setPage(1); } }, [10,20,30,50,100].map((n) => React.createElement("option", { key: n, value: n }, n + "/page")))));
}
ReactDOM.render(React.createElement(App, null), document.getElementById("root"));

